package com.mfg.mes.controller;import com.mfg.common.api.*;import com.mfg.common.exception.BizException;import com.mfg.mes.entity.WorkOrder;import com.mfg.mes.repo.WorkOrderRepository;import lombok.RequiredArgsConstructor;import org.springframework.data.domain.*;import org.springframework.web.bind.annotation.*;import java.math.*;import java.time.*;
/** MES 只执行 ERP 下达需求：工单开工、报工、完工，数量不得超计划。 */
@RestController @RequestMapping("/api/mes/work-orders") @RequiredArgsConstructor public class WorkOrderController{private final WorkOrderRepository repo;@GetMapping public ApiResponse<Page<WorkOrder>> page(@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int size){return ApiResponse.ok(repo.findAll(PageRequest.of(Math.max(page-1,0),Math.min(size,200))));}@PostMapping public ApiResponse<WorkOrder> create(@RequestBody WorkOrder w){w.setStatus("CREATED");w.setCompletedQty(BigDecimal.ZERO);w.setQualifiedQty(BigDecimal.ZERO);w.setScrapQty(BigDecimal.ZERO);return ApiResponse.ok(repo.save(w));}@PostMapping("/{id}/start")public ApiResponse<WorkOrder> start(@PathVariable Long id){WorkOrder w=load(id);if(!"CREATED".equals(w.getStatus())&&!"RELEASED".equals(w.getStatus()))throw BizException.of(ErrorCode.MASTER_DATA_INVALID_STATE,"工单当前不能开工");w.setStatus("STARTED");w.setActualStartTime(LocalDateTime.now());return ApiResponse.ok(repo.save(w));}@PostMapping("/{id}/report")public ApiResponse<WorkOrder> report(@PathVariable Long id,@RequestParam BigDecimal qualifiedQty,@RequestParam(defaultValue="0")BigDecimal scrapQty){WorkOrder w=load(id);if(!"STARTED".equals(w.getStatus()))throw BizException.of(ErrorCode.MASTER_DATA_INVALID_STATE,"只有开工工单可报工");BigDecimal add=qualifiedQty.add(scrapQty);if(w.getCompletedQty().add(add).compareTo(w.getPlanQty())>0)throw BizException.of(ErrorCode.MASTER_DATA_INVALID_STATE,"累计报工数量不能超过计划数量");w.setCompletedQty(w.getCompletedQty().add(add));w.setQualifiedQty(w.getQualifiedQty().add(qualifiedQty));w.setScrapQty(w.getScrapQty().add(scrapQty));if(w.getCompletedQty().compareTo(w.getPlanQty())==0){w.setStatus("COMPLETED");w.setActualEndTime(LocalDateTime.now());}return ApiResponse.ok(repo.save(w));}private WorkOrder load(Long id){return repo.findById(id).orElseThrow(()->BizException.notFound("MES工单",id));}}
